mapper.select:
SELECT T.TEMPLATE_ID, T.TEMPLATE_NM, T.DESCRIPTION, T.USE_YN, (SELECT COUNT(*) FROM SURVEY S WHERE S.TEMPLATE_ID = T.TEMPLATE_ID) AS SURVEY_CNT, T.REGIST_DT, T.UPDT_DT FROM SURVEY_TEMPLATE T
AND T.USE_YN = #{useYn}
AND (T.TEMPLATE_NM LIKE '%' || #{searchKeyword} || '%' OR T.DESCRIPTION LIKE '%' || #{searchKeyword} || '%')
ORDER BY T.TEMPLATE_NM, T.TEMPLATE_ID LIMIT #{recordCountPerPage} OFFSET #{firstIndex}

SELECT COUNT(*) FROM SURVEY_TEMPLATE T
AND T.USE_YN = #{useYn}
AND (T.TEMPLATE_NM LIKE '%' || #{searchKeyword} || '%' OR T.DESCRIPTION LIKE '%' || #{searchKeyword} || '%')

SELECT TEMPLATE_ID, TEMPLATE_NM, DESCRIPTION, USE_YN, REGIST_DT, UPDT_DT
FROM SURVEY_TEMPLATE
WHERE TEMPLATE_ID = #{templateId}

SELECT S.SURVEY_ID, S.TEMPLATE_ID, T.TEMPLATE_NM, S.TITLE, S.DESCRIPTION, S.START_DE, S.END_DE, S.STATUS, S.ANONYMOUS_YN, (SELECT COUNT(*) FROM SURVEY_QUESTION Q WHERE Q.SURVEY_ID = S.SURVEY_ID) AS QUESTION_CNT, (SELECT COUNT(*) FROM SURVEY_PARTICIPATION P WHERE P.SURVEY_ID = S.SURVEY_ID) AS PARTICIPATION_CNT, S.REGIST_DT, S.UPDT_DT FROM SURVEY S LEFT JOIN SURVEY_TEMPLATE T ON T.TEMPLATE_ID = S.TEMPLATE_ID
AND S.STATUS = #{status}
AND (S.TITLE LIKE '%' || #{searchKeyword} || '%' OR S.DESCRIPTION LIKE '%' || #{searchKeyword} || '%')
ORDER BY S.REGIST_DT DESC, S.SURVEY_ID DESC LIMIT #{recordCountPerPage} OFFSET #{firstIndex}

SELECT COUNT(*) FROM SURVEY S
AND S.STATUS = #{status}
AND (S.TITLE LIKE '%' || #{searchKeyword} || '%' OR S.DESCRIPTION LIKE '%' || #{searchKeyword} || '%')

mapper.insert:
INSERT INTO SURVEY (
	SURVEY_ID, TEMPLATE_ID, TITLE, DESCRIPTION, START_DE, END_DE, STATUS, ANONYMOUS_YN, REGIST_DT
) VALUES (
	#{surveyId}, NULLIF(CAST(#{templateId} AS VARCHAR(30)), ''), #{title}, #{description}, #{startDe}, #{endDe}, #{status}, #{anonymousYn}, CURRENT_TIMESTAMP
)

INSERT INTO SURVEY_QUESTION (
	QUESTION_ID, SURVEY_ID, QUESTION_NO, QUESTION_TXT, QUESTION_TYPE, REQUIRED_YN, ORDR, REGIST_DT
) VALUES (
	#{questionId}, #{surveyId}, #{ordr}, #{questionTxt}, #{questionType}, #{requiredYn}, #{ordr}, CURRENT_TIMESTAMP
)

